CREATE TABLE IF NOT EXISTS rfid_cards (id INT AUTO_INCREMENT PRIMARY KEY, uid VARCHAR(50) NOT NULL UNIQUE, student_id INT NOT NULL, status ENUM('active', 'inactive') DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES siswa(id) ON DELETE CASCADE); 
ALTER TABLE siswa DROP COLUMN IF EXISTS rfid_uid; 
